-- "Did you know" facts, sourced from the DidYouKnow_PRODUCTION_READY
-- workbook (850 cards, already filtered by the workbook itself to
-- Publish Status = Ready).
--
-- age_min_months/age_max_months are parsed from the sheet's free-text
-- "Age Range" for filtering; -9 marks a prenatal-relevant card, 9999 marks
-- an open-ended upper bound ("1-6 yrs+"). is_research_based is true only
-- for the 113 cards whose Species is "Fact" or "Research insight" (the
-- ones carrying an Evidence Level and, usually, a Source Citation) -- the
-- other 737 "Human observation" cards have no source to show.
create table if not exists did_you_know_facts (
  id text primary key,
  header text not null,
  card_text text not null,
  india_variant_text text,
  species text not null,
  lane text not null,
  theme text not null,
  age_relevance text not null,
  age_range_raw text not null,
  age_min_months int not null,
  age_max_months int not null,
  geography text not null,
  region text not null,
  feeling text not null,
  audience text not null,
  evidence_level text,
  source_citation text,
  source_url text,
  is_research_based boolean not null default false,
  created_at timestamptz not null default now()
);

comment on table did_you_know_facts is
  'Home screen "Did you know" tile content. Only is_research_based cards show a tappable source; the rest are shown as plain observations, per product decision.';

alter table did_you_know_facts enable row level security;
drop policy if exists "did_you_know_facts_read_all" on did_you_know_facts;
create policy "did_you_know_facts_read_all" on did_you_know_facts for select using (true);

insert into did_you_know_facts (
  id, header, card_text, india_variant_text, species, lane, theme, age_relevance,
  age_range_raw, age_min_months, age_max_months, geography, region, feeling, audience,
  evidence_level, source_citation, source_url, is_research_based
)
